begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4931,"word":"dilapidate","meaning":"使破損","example":"Years of neglect can dilapidate a wooden building.","example_zh":"多年疏於照料，會使木建築破損。","original_meaning":"使破損","original_example":"A dilapidated building.","original_example_zh":"一棟破舊的建築。"},{"source_id":4932,"word":"discernible","meaning":"可辨別的","example":"A faint path was discernible between the tall grasses.","example_zh":"高草間依稀可辨一條小徑。","original_meaning":"可辨別的","original_example":"A discernible pattern.","original_example_zh":"一個可辨識的模式。"},{"source_id":4933,"word":"disclaim","meaning":"否認","example":"The curator chose to disclaim any knowledge of the missing sketch.","example_zh":"策展人選擇否認知道失蹤素描的下落。","original_meaning":"否認","original_example":"Disclaim responsibility.","original_example_zh":"免除責任。"},{"source_id":4934,"word":"discreet","meaning":"謹慎的","example":"The discreet librarian kept the visitor's personal information private.","example_zh":"謹慎館員保護訪客個人資料。","original_meaning":"謹慎的","original_example":"Be discreet.","original_example_zh":"行事謹慎。"},{"source_id":4935,"word":"disguise","meaning":"偽裝","example":"The actor used a hat to disguise himself as the gardener.","example_zh":"演員用帽子把自己偽裝成園丁。","original_meaning":"偽裝","original_example":"Disguise the truth.","original_example_zh":"掩飾真相。"},{"source_id":4936,"word":"disillusion","meaning":"使幻滅","example":"The fake artifact could disillusion the enthusiastic collector.","example_zh":"假文物可能使熱心收藏家幻滅。","original_meaning":"使幻滅","original_example":"Disillusioned with politics.","original_example_zh":"對政治感到幻滅。"},{"source_id":4937,"word":"dismiss","meaning":"駁回","example":"The judge decided to dismiss the unsupported claim.","example_zh":"法官決定駁回缺乏證據的主張。","original_meaning":"駁回","original_example":"Dismiss the case.","original_example_zh":"駁回此案。"},{"source_id":4938,"word":"distill","meaning":"蒸餾","example":"The model showed how to distill water through evaporation and condensation.","example_zh":"模型展示透過蒸發與凝結蒸餾水。","original_meaning":"蒸餾","original_example":"Distill water.","original_example_zh":"蒸餾水。"},{"source_id":4939,"word":"diverge","meaning":"分歧","example":"The two paths began to diverge near the garden gate.","example_zh":"兩條路在花園門旁開始分岔。","original_meaning":"分歧","original_example":"Opinions diverge.","original_example_zh":"意見分歧。"},{"source_id":4940,"word":"downfall","meaning":"衰敗","example":"The novel traced the downfall of the dishonest ruler.","example_zh":"小說追溯不誠實統治者的衰敗。","original_meaning":"衰敗","original_example":"His downfall.","original_example_zh":"他的垮台。"},{"source_id":4941,"word":"dread","meaning":"恐懼","example":"She began to dread speaking before such a large audience.","example_zh":"她開始害怕面對如此多觀眾發言。","original_meaning":"恐懼","original_example":"Dread the exam.","original_example_zh":"害怕考試。"},{"source_id":4942,"word":"dreary","meaning":"陰沉的","example":"The dreary weather kept the village street quiet.","example_zh":"陰沉天氣讓村街冷清。","original_meaning":"陰沉的","original_example":"A dreary day.","original_example_zh":"陰鬱的一天。"},{"source_id":4943,"word":"eavesdrop","meaning":"偷聽","example":"The story warned readers not to eavesdrop on private conversations.","example_zh":"故事提醒讀者不要偷聽私人談話。","original_meaning":"偷聽","original_example":"Eavesdrop on conversations.","original_example_zh":"偷聽對話。"},{"source_id":4944,"word":"edible","meaning":"可食用的","example":"The gardener identified the edible leaves used in the school kitchen.","example_zh":"園丁指出學校廚房使用的可食葉菜。","original_meaning":"可食用的","original_example":"Edible mushrooms.","original_example_zh":"可食用的蘑菇。"},{"source_id":4945,"word":"elate","meaning":"使興高采烈","example":"The successful concert would elate the whole orchestra.","example_zh":"成功音樂會會讓整個管弦樂團興高采烈。","original_meaning":"使興高采烈","original_example":"Elated by the news.","original_example_zh":"因這則消息而欣喜若狂。"},{"source_id":4946,"word":"eligible","meaning":"有資格的","example":"She was eligible to enter the science competition.","example_zh":"她有資格參加科學競賽。","original_meaning":"有資格的","original_example":"Eligible to vote.","original_example_zh":"具備投票資格。"},{"source_id":4947,"word":"elude","meaning":"逃避","example":"The small bird continued to elude the observers among the reeds.","example_zh":"小鳥藏在蘆葦間，持續避開觀察者視線。","original_meaning":"逃避","original_example":"Elude capture.","original_example_zh":"逃脫追捕。"},{"source_id":4948,"word":"emaciate","meaning":"使消瘦","example":"The lecture explained how a prolonged illness can emaciate a patient.","example_zh":"講座解釋長期疾病可能使病人消瘦。","original_meaning":"使消瘦","original_example":"An emaciated body.","original_example_zh":"瘦骨嶙峋的身軀。"},{"source_id":4949,"word":"embed","meaning":"嵌入","example":"The artist decided to embed small stones in the clay.","example_zh":"藝術家決定把小石頭嵌入陶土。","original_meaning":"嵌入","original_example":"Embed the video.","original_example_zh":"嵌入影片。"},{"source_id":4950,"word":"embezzle","meaning":"侵吞","example":"The report accused the fictional treasurer of trying to embezzle public funds.","example_zh":"報告指控虛構財務主管企圖侵吞公款。","original_meaning":"侵吞","original_example":"Embezzle funds.","original_example_zh":"挪用公款。"},{"source_id":4951,"word":"emit","meaning":"發出","example":"The small lamp could emit a gentle blue light.","example_zh":"小燈能發出柔和藍光。","original_meaning":"發出","original_example":"Emit radiation.","original_example_zh":"釋放輻射。"},{"source_id":4952,"word":"emulate","meaning":"效法","example":"The students hoped to emulate the craftsperson's careful technique.","example_zh":"學生希望效法工匠仔細的技法。","original_meaning":"效法","original_example":"Emulate success.","original_example_zh":"效法成功。"},{"source_id":4953,"word":"endanger","meaning":"危及","example":"The model showed how a loose railing could endanger visitors.","example_zh":"模型顯示鬆動欄杆可能危及訪客。","original_meaning":"危及","original_example":"Endanger wildlife.","original_example_zh":"危害野生動物。"},{"source_id":4954,"word":"engrave","meaning":"雕刻","example":"The artist used a tool to engrave a leaf pattern on the wood.","example_zh":"藝術家用工具在木頭雕刻葉紋。","original_meaning":"雕刻","original_example":"Engrave initials.","original_example_zh":"刻上姓名縮寫。"},{"source_id":4955,"word":"engulf","meaning":"吞沒","example":"Thick fog began to engulf the valley.","example_zh":"濃霧開始籠罩山谷。","original_meaning":"吞沒","original_example":"Flames engulfed the building.","original_example_zh":"火焰吞噬了整棟建築。"},{"source_id":4956,"word":"ephemeral","meaning":"短暫的","example":"The ephemeral rainbow vanished as the clouds moved.","example_zh":"雲朵移動後，短暫彩虹消失。","original_meaning":"短暫的","original_example":"Ephemeral beauty.","original_example_zh":"轉瞬即逝的美。"},{"source_id":4957,"word":"equate","meaning":"等同","example":"We should not equate a high price with good craftsmanship.","example_zh":"我們不應把高價等同優良工藝。","original_meaning":"等同","original_example":"Equate wealth with happiness.","original_example_zh":"將財富等同於幸福。"},{"source_id":4958,"word":"erroneous","meaning":"錯誤的","example":"The erroneous measurement made the model lean to one side.","example_zh":"錯誤測量使模型偏向一側。","original_meaning":"錯誤的","original_example":"An erroneous assumption.","original_example_zh":"錯誤的假設。"},{"source_id":4959,"word":"estrange","meaning":"疏遠","example":"The misunderstanding threatened to estrange the two friends.","example_zh":"誤會可能使兩位朋友疏遠。","original_meaning":"疏遠","original_example":"Estranged from family.","original_example_zh":"與家人疏遠。"},{"source_id":4960,"word":"ethic","meaning":"倫理","example":"The club followed an ethic of honesty and mutual help.","example_zh":"社團遵循誠實互助的倫理。","original_meaning":"倫理","original_example":"A strong work ethic.","original_example_zh":"強烈的職業道德。"},{"source_id":4961,"word":"euphemism","meaning":"委婉語","example":"The teacher explained a euphemism used to soften an unpleasant message.","example_zh":"老師解釋一種讓不愉快訊息較溫和的委婉語。","original_meaning":"委婉語","original_example":"Use a euphemism.","original_example_zh":"使用委婉語。"},{"source_id":4962,"word":"evacuate","meaning":"疏散","example":"The staff helped visitors evacuate the building during the drill.","example_zh":"演練時，工作人員協助訪客疏散建築。","original_meaning":"疏散","original_example":"Evacuate the building.","original_example_zh":"疏散大樓。"},{"source_id":4963,"word":"evict","meaning":"驅逐","example":"The historical novel described a landlord's attempt to evict a family.","example_zh":"歷史小說描寫房東企圖驅逐一家人。","original_meaning":"驅逐","original_example":"Evict a tenant.","original_example_zh":"驅逐房客。"},{"source_id":4964,"word":"evoke","meaning":"喚起","example":"The old song could evoke memories of the village.","example_zh":"古老歌曲能喚起對村莊的回憶。","original_meaning":"喚起","original_example":"Evoke memories.","original_example_zh":"喚起回憶。"},{"source_id":4965,"word":"exasperate","meaning":"激怒","example":"The repeated interruptions began to exasperate the speaker.","example_zh":"反覆打斷開始激怒講者。","original_meaning":"激怒","original_example":"Exasperated by delays.","original_example_zh":"因延誤而感到惱火。"},{"source_id":4966,"word":"execute","meaning":"執行","example":"The team was ready to execute the garden plan.","example_zh":"團隊準備執行花園計畫。","original_meaning":"執行","original_example":"Execute the plan.","original_example_zh":"執行計畫。"},{"source_id":4967,"word":"exhilarate","meaning":"使振奮","example":"The first successful test would exhilarate the young inventors.","example_zh":"首次成功測試會讓年輕發明者振奮。","original_meaning":"使振奮","original_example":"An exhilarating experience.","original_example_zh":"令人振奮的體驗。"},{"source_id":4968,"word":"exotic","meaning":"異國的","example":"The botanical garden displayed exotic plants from distant regions.","example_zh":"植物園展示來自遠方地區的異國植物。","original_meaning":"異國的","original_example":"An exotic fruit.","original_example_zh":"一種異國水果。"},{"source_id":4969,"word":"expedient","meaning":"權宜的","example":"Using the spare room was an expedient solution while repairs continued.","example_zh":"維修持續時，使用備用房間是權宜方案。","original_meaning":"權宜的","original_example":"A politically expedient move.","original_example_zh":"一項政治上的權宜之計。"},{"source_id":4970,"word":"expound","meaning":"闡述","example":"The historian began to expound the meaning of the old map.","example_zh":"歷史學家開始闡述古地圖意義。","original_meaning":"闡述","original_example":"Expound a theory.","original_example_zh":"闡述一個理論。"},{"source_id":4971,"word":"extort","meaning":"勒索","example":"The shopkeeper reported an attempt to extort money to the police.","example_zh":"店主向警方報告有人企圖勒索金錢。","original_meaning":"勒索","original_example":"Extort money.","original_example_zh":"勒索錢財。"},{"source_id":4972,"word":"biology","meaning":"生物學","example":"The biology lesson explored the variety of life in a pond.","example_zh":"生物學課探討池塘生命的多樣性。","original_meaning":"生物學","original_example":"Study biology.","original_example_zh":"學習生物學。"},{"source_id":4973,"word":"chemistry","meaning":"化學","example":"The chemistry class used models to compare molecules.","example_zh":"化學課用模型比較分子。","original_meaning":"化學","original_example":"Organic chemistry.","original_example_zh":"有機化學。"},{"source_id":4974,"word":"physics","meaning":"物理學","example":"The physics lesson explained the motion of a pendulum.","example_zh":"物理學課解說鐘擺運動。","original_meaning":"物理學","original_example":"Quantum physics.","original_example_zh":"量子物理學。"},{"source_id":4975,"word":"mathematics","meaning":"數學","example":"The mathematics workshop explored patterns in geometric shapes.","example_zh":"數學工作坊探討幾何形狀中的規律。","original_meaning":"數學","original_example":"Applied mathematics.","original_example_zh":"應用數學。"},{"source_id":4976,"word":"literature","meaning":"文學","example":"The literature class discussed a novel about friendship.","example_zh":"文學課討論一本關於友誼的小說。","original_meaning":"文學","original_example":"English literature.","original_example_zh":"英國文學。"},{"source_id":4977,"word":"medicine","meaning":"醫學","example":"The lecture introduced the history of medicine.","example_zh":"講座介紹醫學歷史。","original_meaning":"醫學","original_example":"Practice medicine.","original_example_zh":"行醫。"},{"source_id":4978,"word":"law","meaning":"法律","example":"The museum explained how law shapes public life.","example_zh":"博物館解說法律如何影響公共生活。","original_meaning":"法律","original_example":"Study law.","original_example_zh":"研讀法律。"},{"source_id":4979,"word":"government","meaning":"政府","example":"The lesson examined the services provided by local government.","example_zh":"課程探討地方政府提供的服務。","original_meaning":"政府","original_example":"Federal government.","original_example_zh":"聯邦政府。"},{"source_id":4980,"word":"enzyme","meaning":"酵素","example":"The model showed how an enzyme helps a chemical reaction.","example_zh":"模型顯示酵素如何幫助化學反應。","original_meaning":"酵素","original_example":"Digestive enzymes.","original_example_zh":"消化酶。"},{"source_id":4981,"word":"protein","meaning":"蛋白質","example":"The students built a protein model using colored beads.","example_zh":"學生用彩色珠子製作蛋白質模型。","original_meaning":"蛋白質","original_example":"Protein synthesis.","original_example_zh":"蛋白質合成。"},{"source_id":4982,"word":"atom","meaning":"原子","example":"The model represented an atom with a central nucleus.","example_zh":"模型以中央原子核呈現原子。","original_meaning":"原子","original_example":"Split the atom.","original_example_zh":"分裂原子。"},{"source_id":4983,"word":"electron","meaning":"電子","example":"The model placed the electron outside the nucleus.","example_zh":"模型把電子放在原子核外。","original_meaning":"電子","original_example":"Electron microscope.","original_example_zh":"電子顯微鏡。"},{"source_id":4984,"word":"proton","meaning":"質子","example":"The atomic model included a proton inside the nucleus.","example_zh":"原子模型包含位於原子核內的質子。","original_meaning":"質子","original_example":"Proton therapy.","original_example_zh":"質子治療。"},{"source_id":4985,"word":"cell","meaning":"細胞","example":"The model revealed several structures inside a cell.","example_zh":"模型呈現細胞內的數種構造。","original_meaning":"細胞","original_example":"A blood cell.","original_example_zh":"一種血球。"},{"source_id":4986,"word":"organ","meaning":"器官","example":"The heart is an organ that pumps blood.","example_zh":"心臟是推動血液的器官。","original_meaning":"器官","original_example":"Organ donation.","original_example_zh":"器官捐贈。"},{"source_id":4987,"word":"species","meaning":"物種","example":"The wetland supports many bird species.","example_zh":"濕地支持許多鳥類物種。","original_meaning":"物種","original_example":"An endangered species.","original_example_zh":"瀕危物種。"},{"source_id":4988,"word":"primate","meaning":"靈長類","example":"The exhibit classified the orangutan as a primate.","example_zh":"展覽把紅毛猩猩歸為靈長類。","original_meaning":"靈長類","original_example":"Humans are primates.","original_example_zh":"人類是靈長類動物。"},{"source_id":4989,"word":"mammal","meaning":"哺乳動物","example":"The dolphin is a mammal.","example_zh":"海豚是哺乳動物。","original_meaning":"哺乳動物","original_example":"A marine mammal.","original_example_zh":"一種海洋哺乳動物。"},{"source_id":4990,"word":"invertebrate","meaning":"無脊椎動物","example":"The jellyfish is an invertebrate without a backbone.","example_zh":"水母是沒有脊椎的無脊椎動物。","original_meaning":"無脊椎動物","original_example":"An invertebrate species.","original_example_zh":"一種無脊椎動物。"},{"source_id":4991,"word":"magnetic","meaning":"磁性的","example":"The magnetic tool could lift the small metal pieces.","example_zh":"磁性工具能提起小金屬片。","original_meaning":"磁性的","original_example":"A magnetic field.","original_example_zh":"磁場。"},{"source_id":4992,"word":"thermal","meaning":"熱的","example":"The thermal image showed warmer and cooler areas of the model house.","example_zh":"熱影像顯示模型屋較暖與較冷區域。","original_meaning":"熱的","original_example":"Thermal energy.","original_example_zh":"熱能。"},{"source_id":4993,"word":"lunar","meaning":"月球的","example":"The lunar exhibit displayed a model of the Moon's surface.","example_zh":"月球展覽展示月表模型。","original_meaning":"月球的","original_example":"A lunar eclipse.","original_example_zh":"月食。"},{"source_id":4994,"word":"volcano","meaning":"火山","example":"The volcano model showed a passage beneath the crater.","example_zh":"火山模型展示火口下方的通道。","original_meaning":"火山","original_example":"An active volcano.","original_example_zh":"一座活火山。"},{"source_id":4995,"word":"tsunami","meaning":"海嘯","example":"The exhibit used a model to explain how a tsunami affects a coast.","example_zh":"展覽用模型解說海嘯如何影響海岸。","original_meaning":"海嘯","original_example":"A devastating tsunami.","original_example_zh":"毀滅性的海嘯。"},{"source_id":4996,"word":"tornado","meaning":"龍捲風","example":"The science model demonstrated the swirling shape of a tornado.","example_zh":"科學模型示範龍捲風旋轉的形狀。","original_meaning":"龍捲風","original_example":"A violent tornado.","original_example_zh":"猛烈的龍捲風。"},{"source_id":4997,"word":"blizzard","meaning":"暴風雪","example":"The blizzard kept the travelers inside the warm shelter.","example_zh":"暴風雪讓旅人留在溫暖庇護所裡。","original_meaning":"暴風雪","original_example":"A winter blizzard.","original_example_zh":"冬季暴風雪。"},{"source_id":4998,"word":"monsoon","meaning":"季風","example":"The monsoon brought heavy seasonal rain to the region.","example_zh":"季風為該地區帶來大量季節性降雨。","original_meaning":"季風","original_example":"The monsoon season.","original_example_zh":"雨季。"},{"source_id":4999,"word":"canyon","meaning":"峽谷","example":"The visitors admired the canyon from a protected viewpoint.","example_zh":"訪客從受保護觀景點欣賞峽谷。","original_meaning":"峽谷","original_example":"The Grand Canyon.","original_example_zh":"大峽谷。"},{"source_id":5000,"word":"delta","meaning":"三角洲","example":"The river formed a broad delta where it met the sea.","example_zh":"河流在入海處形成寬廣三角洲。","original_meaning":"三角洲","original_example":"A river delta.","original_example_zh":"河流三角洲。"},{"source_id":5001,"word":"plateau","meaning":"高原","example":"The plateau rose above the surrounding valleys.","example_zh":"高原高出周圍山谷。","original_meaning":"高原","original_example":"A vast plateau.","original_example_zh":"一片廣闊的高原。"},{"source_id":5002,"word":"reef","meaning":"礁","example":"The reef provided shelter for many small fish.","example_zh":"礁為許多小魚提供藏身處。","original_meaning":"礁","original_example":"A coral reef.","original_example_zh":"一座珊瑚礁。"},{"source_id":5003,"word":"prairie","meaning":"草原","example":"The prairie stretched across a broad grassy plain.","example_zh":"草原延伸在寬廣青草平原上。","original_meaning":"草原","original_example":"The open prairie.","original_example_zh":"開闊的草原。"},{"source_id":5004,"word":"tundra","meaning":"凍原","example":"The tundra landscape had low plants and no tall trees.","example_zh":"凍原地景有低矮植物，沒有高大樹木。","original_meaning":"凍原","original_example":"Arctic tundra.","original_example_zh":"北極苔原。"},{"source_id":5005,"word":"savanna","meaning":"莽原","example":"The savanna had wide grasslands with scattered trees.","example_zh":"莽原有寬廣草地與零星樹木。","original_meaning":"莽原","original_example":"The African savanna.","original_example_zh":"非洲大草原。"},{"source_id":5006,"word":"oasis","meaning":"綠洲","example":"The oasis offered green plants amid the dry desert.","example_zh":"綠洲在乾燥沙漠中提供綠色植物。","original_meaning":"綠洲","original_example":"A desert oasis.","original_example_zh":"沙漠中的綠洲。"},{"source_id":5007,"word":"archipelago","meaning":"群島","example":"The map showed an archipelago of many small islands.","example_zh":"地圖顯示由許多小島組成的群島。","original_meaning":"群島","original_example":"A tropical archipelago.","original_example_zh":"熱帶群島。"},{"source_id":5008,"word":"democracy","meaning":"民主","example":"The civics lesson explored how democracy gives citizens a voice.","example_zh":"公民課探討民主如何讓公民發聲。","original_meaning":"民主","original_example":"A healthy democracy.","original_example_zh":"健康的民主制度。"},{"source_id":5009,"word":"governor","meaning":"州長","example":"The governor visited the school to discuss the new library.","example_zh":"州長到學校討論新圖書館。","original_meaning":"州長","original_example":"The state governor.","original_example_zh":"州長。"},{"source_id":5010,"word":"mayor","meaning":"市長","example":"The mayor welcomed volunteers to the riverside cleanup.","example_zh":"市長歡迎志工參加河岸清潔。","original_meaning":"市長","original_example":"The city mayor.","original_example_zh":"市長。"},{"source_id":5011,"word":"prosecutor","meaning":"檢察官","example":"The prosecutor presented documents during the trial.","example_zh":"檢察官在審判中提出文件。","original_meaning":"檢察官","original_example":"The chief prosecutor.","original_example_zh":"首席檢察官。"},{"source_id":5012,"word":"attorney","meaning":"律師","example":"The attorney explained the agreement to her client.","example_zh":"律師向當事人解說協議。","original_meaning":"律師","original_example":"A defense attorney.","original_example_zh":"辯護律師。"},{"source_id":5013,"word":"jury","meaning":"陪審團","example":"The jury listened carefully to the evidence.","example_zh":"陪審團仔細聽取證據。","original_meaning":"陪審團","original_example":"A grand jury.","original_example_zh":"大陪審團。"},{"source_id":5014,"word":"parole","meaning":"假釋","example":"The board granted parole under a supervision plan.","example_zh":"委員會依監督計畫准予假釋。","original_meaning":"假釋","original_example":"Released on parole.","original_example_zh":"獲准假釋。"},{"source_id":5015,"word":"cartel","meaning":"卡特爾；企業聯合壟斷組織","example":"The economics lesson examined how a cartel can limit competition.","example_zh":"經濟課探討卡特爾如何限制競爭。","original_meaning":"卡特爾","original_example":"A drug cartel.","original_example_zh":"一個毒品集團。"},{"source_id":5016,"word":"conglomerate","meaning":"企業集團","example":"The conglomerate owned businesses in several industries.","example_zh":"企業集團擁有數種產業的公司。","original_meaning":"企業集團","original_example":"A media conglomerate.","original_example_zh":"一家媒體集團。"},{"source_id":5017,"word":"malware","meaning":"惡意軟體","example":"The cybersecurity lesson explained how malware can damage computer systems.","example_zh":"網路安全課解說惡意軟體可能損害電腦系統。","original_meaning":"惡意軟體","original_example":"Infected by malware.","original_example_zh":"感染惡意軟體。"},{"source_id":5018,"word":"pixel","meaning":"像素","example":"The enlarged picture revealed each square pixel.","example_zh":"放大圖片呈現每個方形像素。","original_meaning":"像素","original_example":"High pixel density.","original_example_zh":"高像素密度。"},{"source_id":5019,"word":"interface","meaning":"介面","example":"The simple interface helped users find books quickly.","example_zh":"簡單介面幫使用者快速找到書。","original_meaning":"介面","original_example":"A user interface.","original_example_zh":"使用者介面。"},{"source_id":5020,"word":"fiber","meaning":"光纖","example":"The technician demonstrated a fiber carrying light signals.","example_zh":"技術人員示範光纖傳輸光訊號。","original_meaning":"光纖","original_example":"Fiber optic cable.","original_example_zh":"光纖電纜。"},{"source_id":5021,"word":"drone","meaning":"無人機","example":"The research drone photographed the wetland from above.","example_zh":"研究無人機從上方拍攝濕地。","original_meaning":"無人機","original_example":"A surveillance drone.","original_example_zh":"一架監視無人機。"},{"source_id":5022,"word":"reactor","meaning":"反應爐","example":"The model showed how heat from a reactor can generate electricity.","example_zh":"模型展示反應爐熱能如何用來發電。","original_meaning":"反應爐","original_example":"A nuclear reactor.","original_example_zh":"核反應爐。"},{"source_id":5023,"word":"artery","meaning":"動脈","example":"The model showed an artery carrying blood away from the heart.","example_zh":"模型展示動脈把血液帶離心臟。","original_meaning":"動脈","original_example":"A blocked artery.","original_example_zh":"阻塞的動脈。"},{"source_id":5024,"word":"spine","meaning":"脊椎","example":"The skeleton model showed the spine supporting the upper body.","example_zh":"骨骼模型展示脊椎支撐上半身。","original_meaning":"脊椎","original_example":"A spinal injury.","original_example_zh":"脊椎受傷。"},{"source_id":5025,"word":"skull","meaning":"頭骨","example":"The museum displayed a model of the human skull.","example_zh":"博物館展示人類頭骨模型。","original_meaning":"頭骨","original_example":"A fractured skull.","original_example_zh":"顱骨骨折。"},{"source_id":5026,"word":"rib","meaning":"肋骨","example":"The rib model showed part of the chest's protective cage.","example_zh":"肋骨模型展示胸廓保護構造的一部分。","original_meaning":"肋骨","original_example":"A broken rib.","original_example_zh":"一根斷肋骨。"},{"source_id":5027,"word":"pelvis","meaning":"骨盆","example":"The anatomy model showed the pelvis supporting the spine.","example_zh":"解剖模型展示骨盆支撐脊椎。","original_meaning":"骨盆","original_example":"A pelvic fracture.","original_example_zh":"骨盆骨折。"},{"source_id":5028,"word":"tendon","meaning":"肌腱","example":"The model showed a tendon connecting muscle to bone.","example_zh":"模型展示肌腱連接肌肉與骨頭。","original_meaning":"肌腱","original_example":"A torn tendon.","original_example_zh":"斷裂的肌腱。"},{"source_id":5029,"word":"ligament","meaning":"韌帶","example":"The model showed a ligament connecting one bone to another.","example_zh":"模型展示韌帶把一根骨頭連接另一根。","original_meaning":"韌帶","original_example":"A torn ligament.","original_example_zh":"韌帶撕裂。"},{"source_id":5030,"word":"cartilage","meaning":"軟骨","example":"The model showed cartilage cushioning the ends of bones in a joint.","example_zh":"模型展示軟骨緩衝關節內骨端。","original_meaning":"軟骨","original_example":"Knee cartilage.","original_example_zh":"膝蓋軟骨。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-dilapidate-01-v1","level":"senior","word":"dilapidate","sort_order":1,"sense":"使破損","alt_zh":"高中生與成年導覽員從安全圍欄外觀看空置破舊木屋。","example":"Years of neglect can dilapidate a wooden building.","example_zh":"多年疏於照料，會使木建築破損。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dilapidate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-discernible-01-v1","level":"senior","word":"discernible","sort_order":1,"sense":"可辨別的","alt_zh":"成年嚮導與高中生在安全觀景臺指向草地間淡淡路徑。","example":"A faint path was discernible between the tall grasses.","example_zh":"高草間依稀可辨一條小徑。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/discernible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disclaim-01-v1","level":"senior","word":"disclaim","sort_order":1,"sense":"否認","alt_zh":"成年策展人在博物館辦公室與調查員平靜核對文件，無真實指控。","example":"The curator chose to disclaim any knowledge of the missing sketch.","example_zh":"策展人選擇否認知道失蹤素描的下落。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disclaim-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-discreet-01-v1","level":"senior","word":"discreet","sort_order":1,"sense":"謹慎的","alt_zh":"成年館員在櫃臺把無字私人文件收進封閉資料夾，高中訪客等候。","example":"The discreet librarian kept the visitor's personal information private.","example_zh":"謹慎館員保護訪客個人資料。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/discreet-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disguise-01-v1","level":"senior","word":"disguise","sort_order":1,"sense":"偽裝","alt_zh":"高中戲劇演員在成年老師旁戴園藝帽、拿安全澆水壺排練。","example":"The actor used a hat to disguise himself as the gardener.","example_zh":"演員用帽子把自己偽裝成園丁。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disguise-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-disillusion-01-v1","level":"senior","word":"disillusion","sort_order":1,"sense":"使幻滅","alt_zh":"成年收藏家與館員失望查看被證實是仿製品的陶器，無詐騙方法。","example":"The fake artifact could disillusion the enthusiastic collector.","example_zh":"假文物可能使熱心收藏家幻滅。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/disillusion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dismiss-01-v1","level":"senior","word":"dismiss","sort_order":1,"sense":"駁回","alt_zh":"成年法官在法庭查看文件後平靜宣布決定，律師聆聽。","example":"The judge decided to dismiss the unsupported claim.","example_zh":"法官決定駁回缺乏證據的主張。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dismiss-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-distill-01-v1","level":"senior","word":"distill","sort_order":1,"sense":"蒸餾","alt_zh":"成年科學教師向高中生展示封閉水蒸餾教具，無酒精、數值或操作步驟。","example":"The model showed how to distill water through evaporation and condensation.","example_zh":"模型展示透過蒸發與凝結蒸餾水。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/distill-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-diverge-01-v1","level":"senior","word":"diverge","sort_order":1,"sense":"分歧","alt_zh":"高中生與成年嚮導在安全花園入口觀察兩條向不同方向延伸的步道。","example":"The two paths began to diverge near the garden gate.","example_zh":"兩條路在花園門旁開始分岔。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/diverge-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-downfall-01-v1","level":"senior","word":"downfall","sort_order":1,"sense":"衰敗","alt_zh":"高中文學課看虛構成年統治者離開空王座的故事插畫，無傷害。","example":"The novel traced the downfall of the dishonest ruler.","example_zh":"小說追溯不誠實統治者的衰敗。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/downfall-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dread-01-v1","level":"senior","word":"dread","sort_order":1,"sense":"恐懼","alt_zh":"成年老師在禮堂後臺溫柔鼓勵緊張高中講者，同學友善等候。","example":"She began to dread speaking before such a large audience.","example_zh":"她開始害怕面對如此多觀眾發言。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dread-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-dreary-01-v1","level":"senior","word":"dreary","sort_order":1,"sense":"陰沉的","alt_zh":"灰天細雨中的安靜村街，成年居民在乾燥室內閱讀。","example":"The dreary weather kept the village street quiet.","example_zh":"陰沉天氣讓村街冷清。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/dreary-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-eavesdrop-01-v1","level":"senior","word":"eavesdrop","sort_order":1,"sense":"偷聽","alt_zh":"高中生在成年老師引導下討論尊重隱私的故事圖卡，無竊聽方法。","example":"The story warned readers not to eavesdrop on private conversations.","example_zh":"故事提醒讀者不要偷聽私人談話。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/eavesdrop-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-edible-01-v1","level":"senior","word":"edible","sort_order":1,"sense":"可食用的","alt_zh":"成年園藝老師向高中生展示整齊種植的萵苣菜圃，不採食野生植物。","example":"The gardener identified the edible leaves used in the school kitchen.","example_zh":"園丁指出學校廚房使用的可食葉菜。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/edible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elate-01-v1","level":"senior","word":"elate","sort_order":1,"sense":"使興高采烈","alt_zh":"高中樂團與成年指揮演出後開心擊掌、接受掌聲。","example":"The successful concert would elate the whole orchestra.","example_zh":"成功音樂會會讓整個管弦樂團興高采烈。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-eligible-01-v1","level":"senior","word":"eligible","sort_order":1,"sense":"有資格的","alt_zh":"成年老師核對高中生報名文件和模型作品，友善點頭。","example":"She was eligible to enter the science competition.","example_zh":"她有資格參加科學競賽。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/eligible-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-elude-01-v1","level":"senior","word":"elude","sort_order":1,"sense":"逃避","alt_zh":"高中觀鳥團與成年老師在安全小屋遠距尋找蘆葦中僅露部分的小鳥。","example":"The small bird continued to elude the observers among the reeds.","example_zh":"小鳥藏在蘆葦間，持續避開觀察者視線。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/elude-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-emaciate-01-v1","level":"senior","word":"emaciate","sort_order":1,"sense":"使消瘦","alt_zh":"大學醫學圖書館裡，成年教師向成年學生講解資料，桌上只有書籍與抽象圖表，沒有患者或人體模型。","example":"The lecture explained how a prolonged illness can emaciate a patient.","example_zh":"講座解釋長期疾病可能使病人消瘦。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/emaciate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-embed-01-v1","level":"senior","word":"embed","sort_order":1,"sense":"嵌入","alt_zh":"成年陶藝老師與高中生在桌上把圓滑小石嵌入柔軟陶土裝飾板。","example":"The artist decided to 